import{c as i,ah as a,L as t,O as e}from"./chunks/framework.YKVbmyBD.js";const g=JSON.parse('{"title":"安装 Linux 注意事项","description":"","frontmatter":{},"headers":[],"relativePath":"fovlin-notes/linux-guide/install-linux-options.md","filePath":"fovlin-notes/linux-guide/install-linux-options.md"}'),n={name:"fovlin-notes/linux-guide/install-linux-options.md"};function l(p,s,h,d,k,r){return a(),t("div",null,[...s[0]||(s[0]=[e(`<h1 id="安装-linux-注意事项" tabindex="-1">安装 Linux 注意事项 <a class="header-anchor" href="#安装-linux-注意事项" aria-label="Permalink to “安装 Linux 注意事项”">​</a></h1><h2 id="关于硬盘挂载" tabindex="-1">关于硬盘挂载 <a class="header-anchor" href="#关于硬盘挂载" aria-label="Permalink to “关于硬盘挂载”">​</a></h2><p>硬盘挂载将直接影响 Linux 系统的使用体验，所有的硬盘都位于 <code>/dev</code> 目录下。</p><h3 id="分区" tabindex="-1">分区 <a class="header-anchor" href="#分区" aria-label="Permalink to “分区”">​</a></h3><p>在安装时，对硬盘进行分区，Linux 系统下共需要以下分区：</p><table tabindex="0"><thead><tr><th>分区</th><th>描述</th><th>分区类型</th></tr></thead><tbody><tr><td>/</td><td>系统根目录</td><td>ext4 文件系统</td></tr><tr><td>/boot</td><td>引导分区</td><td>EFI 系统分区(FAT32)</td></tr><tr><td>/home</td><td>用户数据目录</td><td>ext4 文件系统</td></tr><tr><td>swap</td><td>交换分区</td><td>swap 分区</td></tr></tbody></table><p>其中 <code>/</code> 分区为系统根目录，<code>/boot</code> 分区为引导分区，<code>/home</code> 分区为用户数据目录，<code>swap</code> 分区为交换分区，其中 <code>swap</code> 和 <code>/home</code> 分区是可选的。</p><p><code>/home</code> 分区可以将用户数据和系统数据分开存储，这样当系统空间不足时，用户数据不会被系统数据所覆盖。</p><p>同时在重装或更换其他 Linux 系统时，可以保留用户数据，避免数据丢失。</p><h3 id="推荐大小" tabindex="-1">推荐大小 <a class="header-anchor" href="#推荐大小" aria-label="Permalink to “推荐大小”">​</a></h3><table tabindex="0"><thead><tr><th>分区</th><th>推荐大小</th></tr></thead><tbody><tr><td>/</td><td>30G以上</td></tr><tr><td>/boot</td><td>1G</td></tr><tr><td>/home</td><td>30G以上</td></tr></tbody></table><p>在安装时，请根据实际情况选择分区，并确保分区大小正确。</p><p>对于 Ubuntu 以及大部分 Linux 系统，都会存在图形化安装界面，选择并分区即可。</p><p>而对于手动安装的 Linux 系统，需要自己手动进行分区。</p><h3 id="手动分区并挂载" tabindex="-1">手动分区并挂载 <a class="header-anchor" href="#手动分区并挂载" aria-label="Permalink to “手动分区并挂载”">​</a></h3><p>对于需要手动安装的 Linux 系统，需要自己手动在 Live 环境进行分区。</p><p>使用 <code>lsblk</code> 命令查看硬盘及其分区信息。</p><div class="language-txt"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>NAME        MAJ:MIN RM   SIZE RO TYPE MOUNTPOINT</span></span>
<span class="line"><span>sda           8:0    0 953.9G  0 disk</span></span>
<span class="line"><span>├─sda1        8:1    0 256.0G  0 part </span></span>
<span class="line"><span>└─sda2        8:2    0 687.9G  0 part</span></span>
<span class="line"><span>nvme0n1     259:0    0 953.9G  0 disk </span></span>
<span class="line"><span>├─nvme0n1p1 259:1    0   0.9G  0 part</span></span>
<span class="line"><span>├─nvme0n1p2 259:2    0 256.0G  0 part</span></span>
<span class="line"><span>└─nvme0n1p3 259:4    0 697.0G  0 part</span></span></code></pre></div><p>假设我们要在 sda 硬盘上安装系统，使用 <code>cfdisk</code> 命令进行分区。</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cfdisk</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/sda</span></span></code></pre></div><p>正确进行分区后至少有以下分区，如：</p><div class="language-txt"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>NAME        MAJ:MIN RM   SIZE RO TYPE MOUNTPOINT</span></span>
<span class="line"><span>sda           8:0    0 953.9G  0 disk</span></span>
<span class="line"><span>├─nvme0n1p1 259:1    0  14.9G  0 part [SWAP]    #可选但推荐</span></span>
<span class="line"><span>├─nvme0n1p2 259:2    0   250G  0 part /</span></span>
<span class="line"><span>├─nvme0n1p3 259:3    0     1G  0 part /boot/efi</span></span>
<span class="line"><span>└─nvme0n1p4 259:4    0 687.9G  0 part /home     #可选但推荐</span></span>
<span class="line"><span>nvme0n1     259:0    0 953.9G  0 disk </span></span>
<span class="line"><span>├─nvme0n1p1 259:1    0   0.9G  0 part</span></span>
<span class="line"><span>├─nvme0n1p2 259:2    0 256.0G  0 part</span></span>
<span class="line"><span>└─nvme0n1p3 259:4    0 697.0G  0 part</span></span></code></pre></div><p>在手动挂载前需要保证其为正确的文件系统，若不是，需要手动格式化。</p><p>对于格式化为 ext4 文件系统，使用以下命令：</p><div class="language-txt"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkfs.ext4 /dev/&lt;分区路径&gt;</span></span></code></pre></div><p>对于格式化为 FAT32 文件系统，使用以下命令：</p><div class="language-txt"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkfs.fat -F 32 /dev/&lt;分区路径&gt;</span></span></code></pre></div><p>对于格式化为 swap 分区，使用以下命令：</p><div class="language-txt"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkswap /dev/&lt;分区路径&gt;</span></span></code></pre></div><h2 id="管理网络" tabindex="-1">管理网络 <a class="header-anchor" href="#管理网络" aria-label="Permalink to “管理网络”">​</a></h2><p>对于一些需要手动安装的系统，如 Arch Linux 系统，需要手动安装以下软件来管理网络。</p><p><strong>NetworkManager</strong> 是 Linux 系统中的网络管理软件，用于管理网络连接。</p><p>在 Arch Linux 系统中，可以使用以下命令安装 NetworkManager：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pacman</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> networkmanager</span></span></code></pre></div><h2 id="图形化界面" tabindex="-1">图形化界面 <a class="header-anchor" href="#图形化界面" aria-label="Permalink to “图形化界面”">​</a></h2><p>Linux 系统有很多不同的桌面环境，如 GNOME、KDE、Xfce、Mate、LXDE 等，这些桌面环境提供了完整的图形化体验，除此之外，你也可以安装窗口管理器来手动配置图形界面，如 Hyprland。</p><p>Ubuntu 系统默认安装经过配置的 GNOME 桌面环境，对于手动安装的系统，可以自行选择桌面环境。</p><p>如下列举常用的2个桌面环境，Gnome 和 KDE 的安装：</p><h3 id="gnome" tabindex="-1">Gnome <a class="header-anchor" href="#gnome" aria-label="Permalink to “Gnome”">​</a></h3><p>对于 Ubuntu 安装 Gnome 桌面环境，提供两种选择，分别是 ubuntu-desktop 和 gnome，前者是 Ubuntu 默认的桌面环境，即对 Gnome 的修改，后者是 Gnome 桌面环境。 可以使用以下命令安装：</p><ul><li>Ubuntu 默认的桌面环境：</li></ul><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ubuntu-desktop</span></span></code></pre></div><ul><li>Gnome 桌面环境：</li></ul><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gnome</span></span></code></pre></div><p>对于 Arch Linux 系统，可以使用以下命令安装：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pacman</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gnome</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gdm</span></span></code></pre></div><p>选择两者任意一个安装后，启动 gdm 显示管理器。</p><p>启动 gdm 显示管理器可以使用以下命令：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --now</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gdm</span></span></code></pre></div><h3 id="kde" tabindex="-1">KDE <a class="header-anchor" href="#kde" aria-label="Permalink to “KDE”">​</a></h3><p>KDE 是一个开源的桌面环境，KDE 桌面环境提供了丰富的功能，如文件管理器、浏览器、音乐播放器、视频播放器、计算器、文字编辑器、图像处理工具、网络工具、系统工具等。</p><p>KDE 桌面环境同样分为两种，分别是 kubuntu-desktop 和 kde-plasma-desktop，前者是 Ubuntu 默认的桌面环境，后者是 KDE 桌面环境，安装可以使用以下命令：</p><ul><li>Ubuntu 默认的桌面环境：</li></ul><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kubuntu-desktop</span></span></code></pre></div><ul><li>KDE 桌面环境：</li></ul><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kde-plasma-desktop</span></span></code></pre></div><ul><li>Arch Linux 系统，可以使用以下命令安装：</li></ul><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pacman</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> plasma</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sddm</span></span></code></pre></div><p>选择两者任意一个安装后，启动 sddm 显示管理器。</p><p>启动 sddm 显示管理器可以使用以下命令：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --now</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sddm</span></span></code></pre></div>`,61)])])}const c=i(n,[["render",l]]);export{g as __pageData,c as default};
